96	    /**
97	     * Where the system property fortress.inference.trace names a file, each
98	     * instance that the bound rules below give in place of the instance the
99	     * earlier rules gave is appended to it, one line per type parameter.
100	     */
101	    private static final String TRACE = System.getProperty("fortress.inference.trace");
102	
103	    private static void traceInstance(String rule, Object decl, String param, Object before, Object after, Object args) {
104	        if (TRACE == null) return;
105	        synchronized (EvaluatorBase.class) {
106	            try {
107	                FileWriter w = new FileWriter(TRACE, true);
108	                w.write(rule + "\t" + decl + "\t" + param + "\t" + before + "\t" + after + "\t" + args + "\n");
109	                w.close();
110	            }
111	            catch (IOException ex) {
112	                // the trace is best effort
113	            }
114	        }
115	    }
