155	    /**
156	     * The bound of the type parameter n: the upper end of its interval, the
157	     * meet of its declared bounds, or Any where it has none.
158	     */
159	    private static FType boundOf(LatticeIntervalMap<String, FType, TypeLatticeOps> abm, String n) {
160	        FType upper = abm.getUpper(n);
161	        return upper == null ? FTypeTop.ONLY : upper;
