201	    /**
202	     * The hint of the overloaded big operator whose overload this thread is
203	     * choosing and instantiating, set by instantiateBigOperator around
204	     * OverloadedFunction.bestMatch alone.  bestMatch evaluates no Fortress
205	     * expression and starts and joins no task, so no other evaluation runs on
206	     * this thread while it is set; inferAndInstantiateGenericFunction reads it
207	     * only for an overload of the operator it names.
208	     */
209	    private static final ThreadLocal<BigOperatorHint> choosing = new ThreadLocal<BigOperatorHint>();
210	
211	    /**
212	     * Whether a reduction's or a comprehension's big operator value opv has
213	     * static parameters to instantiate: a generic function, or an overloaded
214	     * one with a generic overload.
215	     */
216	    public static boolean instantiable(FValue opv) {
217	        if (opv instanceof GenericFunctionOrConstructor) return true;
218	        if (!(opv instanceof OverloadedFunction)) return false;
219	        for (Overload o : ((OverloadedFunction) opv).getOverloads()) {
220	            if (o.getFn() instanceof GenericFunctionOrMethod) return true;
221	        }
222	        return false;
223	    }
224	
225	    /**
226	     * The big operator value opv, which instantiable accepts, applied to no
227	     * argument as a reduction or a comprehension that writes no static
228	     * argument applies it: the declaration is chosen and instantiated under
229	     * the hint h, outside the per-argument-type caches, which hold the
230	     * instance that no hint gives, and the instance is then applied with no
231	     * hint in reach.
232	     */
233	    public static FValue instantiateBigOperator(FValue opv, BigOperatorHint h, HasAt site) {
234	        List<FValue> none = Collections.<FValue>emptyList();
235	        SingleFcn inst;
236	        try {
237	            if (opv instanceof GenericFunctionOrConstructor) {
238	                GenericFunctionOrConstructor g = (GenericFunctionOrConstructor) opv;
239	                inst = inferAndInstantiateGenericFunction(none, g, g.getWithin(), h);
240	            } else {
241	                OverloadedFunction of = (OverloadedFunction) opv;
242	                BigOperatorHint before = choosing.get();
243	                choosing.set(h);
244	                try {
245	                    inst = of.bestMatch(none, of.getOverloads());
246	                }
247	                finally {
248	                    if (before == null) choosing.remove();
249	                    else choosing.set(before);
250	                }
251	                if (inst instanceof GenericFunctionOrMethod) {
252	                    return bug(site, errorMsg("overload res yielded generic ", inst));
253	                }
254	            }
255	        }
256	        catch (FortressException ex) {
257	            throw ex.setWhere(site);
258	        }
259	        return inst.functionInvocation(none, site);
260	    }
