506	    /**
507	     * The environment in which the bounds of g's static parameters and the
508	     * coercions of its arguments are read: where g is declared, as for a
509	     * generic function, and for a method that a trait declares, the trait's
510	     * method environment (GenericMethod.getTypeEnv).
511	     */
512	    private static Environment declarationEnv(GenericFunctionOrMethod g) {
513	        return g instanceof GenericMethod ? ((GenericMethod) g).getTypeEnv() : g.getWithin();
514	    }
